#!/usr/bin/env python3
"""Initial curated registry, not a claim that every endpoint was fetched."""
from pathlib import Path
import json
BASE=Path(__file__).resolve().parent
sources=[]
def add(id,publisher,homepage,feed,tags,states=None,role='media_lead',evidence=None,note=None,method='rss_metadata',api=None):
 sources.append({'id':id,'publisher':publisher,'homepage':homepage,'feed_urls':[feed] if feed else [],'api_urls':api or [],'source_role':role,'topic_tags':tags,'geography':{'country':'US','scope':'state' if states else 'national','state_codes':states or ['ALL_50','DC']},'access_method':method,'robots_url':homepage.rstrip('/')+'/robots.txt','robots_notes':{'status':'not_checked','evidence':None},'terms_notes':{'checked_at':'2026-10-03' if evidence else None,'evidence_url':evidence,'observation':note or 'No source-specific republication conditions have been established in this registry; collector stores link metadata only.'},'last_checked':None,'collector_status':'ready_to_probe' if feed and method=='rss_metadata' else 'research_search_required','next_refresh':None,'refresh_interval_hours':24,'store_description':False})
